\begin{tikzpicture}
\begin{axis}[
    width=0.68\textwidth,
    height=0.46\textwidth,
    xmin=-2, xmax=4,
    ymin=-4, ymax=8,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-1,0,1,2,3},
    ytick={-3,0,3,6},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-1.2:3.2, samples=150] {2*(x-1)^2-3};
\addplot[only marks, mark=*] coordinates {(1,-3)};
\node[anchor=north west] at (axis cs:1,-3) {\((1,-3)\)};
\node[anchor=south] at (axis cs:1,0.4) {\(y=2(x-1)^2-3\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.68\textwidth,
    height=0.44\textwidth,
    xmin=-4.5, xmax=4.5,
    ymin=-3, ymax=3,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-3,0,3},
    ytick={-2,0,2},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    axis equal image,
]
\addplot[very thick, domain=0:360, samples=250] ({3*cos(x)}, {2*sin(x)});
\addplot[only marks, mark=*] coordinates {(0,0) (3,0) (-3,0) (0,2) (0,-2)};
\node[anchor=south west] at (axis cs:0,0) {\((0,0)\)};
\node[anchor=south] at (axis cs:1.5,0) {\(a=3\)};
\node[anchor=west] at (axis cs:0,1) {\(b=2\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.72\textwidth,
    height=0.48\textwidth,
    xmin=-8, xmax=8,
    ymin=-5, ymax=5,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-6,-3,0,3,6},
